class Robot:
    def __init__(self, game, code, markers, id):
        self.game = game
        self.code = code
        self.markers = markers
        self.id = id
        self.position = (0, 0)
        self.direction = 'N'
        self.alive = True

    def move(self, direction):
        if direction == 'N':
            self.position = (self.position[0], self.position[1] + 1)
        elif direction == 'S':
            self.position = (self.position[0], self.position[1] - 1)
        elif direction == 'E':
            self.position = (self.position[0] + 1, self.position[1])
        elif direction == 'W':
            self.position = (self.position[0] - 1, self.position[1])
        self.direction = direction

    def mark(self, marker):
        self.markers.append(marker)

    def unmark(self, marker):
        self.markers.remove(marker)

    def is_alive(self):
        return self.alive

    def kill(self):
        self.alive = False

    def __repr__(self):
        return f'Robot({self.id}, {self.code}, {self.markers}, {self.position}, {self.direction})'
