COMMANDTYPES = {'*': 'all', 'r':'select', 'a': 'insert', 'd': 'delete'}

class Database:
    def __init__(self, dbname):
        self.dbname = dbname
        self.conn = sqlite3.connect(dbname)
        self.cursor = self.conn.cursor()

    def __del__(self):
        self.conn.close()

    def execute(self, command):
        commandtype = command[0]
        if commandtype not in COMMANDTYPES:
            raise ValueError('Invalid command type')
        if commandtype == '*':
            self.cursor.execute(command)
            return self.cursor.fetchall()
        elif commandtype == 'r':
            self.cursor.execute(command)
            return self.cursor.fetchall()
        elif commandtype == 'a':
            self.cursor.execute(command)
            self.conn.commit()
            return None
        elif commandtype == 'd':
            self.cursor.execute(command)
            self.conn.commit()
            return None
        else:
            raise ValueError('Invalid command type')

    def select(self, command):
        commandtype = command[0]
        if commandtype not in COMMANDTYPES:
            raise ValueError('Invalid command type')
        if commandtype == '*':
            self.cursor.execute(command)
            return self.cursor.fetchall()
        elif commandtype == 'r':
            self.cursor.execute(command)
            return self.cursor.fetchall()
        else:
            raise ValueError('Invalid command type')

    def insert(self, command):
        commandtype = command[0]
        if commandtype not in COMMANDTYPES:
            raise ValueError('Invalid command type')
        if commandtype == 'a':
            self.cursor.execute(command)
            self.conn.commit()
            return None
        else:
            raise ValueError('Invalid command type')

    def delete(self, command):
        commandtype = command[0]
        if commandtype not in COMMANDTYPES:
            raise ValueError('Invalid command type')
        if commandtype == 'd':
            self.cursor.execute(command)
            self.conn.commit()
            return None
        else:
            raise ValueError('Invalid command type')
