class Solution:

    def timeTaken(self, edges: list[list[int]]) -> list[int]:
        n = len(edges) + 1
        ans = [0] * n
        tree = [[] for _ in range(n)]
        dp = [Top2()] * n
        for u, v in edges:
            tree[u].append(v)
