        top1 = Node()
        top2 = Node()
        for v in tree[u]:
            if v == prev:
                continue
            time = self._dfs(tree, v, u, dp) + self._getTime(v)
            if time >= top1.time:
                top2 = top1
                top1 = Node(v, time)
            elif time > top2.time:
                top2 = Node(v, time)
        dp[u] = Top2(top1, top2)
        return top1.time

    def _reroot(self, tree: list[list[int]], u: int, prev: int, maxTime: int, dp: list[Top2], ans: list[int]) -> None:
