class Solution:

    def maxDepth(self, root: 'Node') -> int:
        if root is None:
            return 0
        depth = 0
        queue = [root]
        while queue:
            depth += 1
            n = len(queue)
            for _ in range(n):
                node = queue.pop(0)
                for child in node.children:
                    queue.append(child)
        return depth

