    public:

        int maxIncreasingGroups(vector<int>& usageLimits) {
            sort(usageLimits.begin(), usageLimits.end());
            int k, n = (0, usageLimits.size());
            for (i = n - 1; i >= 0; i--) {
                if (usageLimits[i] > k) {
                    k += 1;
                    usageLimits[i] -= k;
                }
                if (i + 1 < n) {
                    usageLimits[i + 1] += usageLimits[i];
                }
            }
            return k;
        }
